// 节点功能：对获取到的视频进行分片处理
// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)

const CHUNK_SIZE = 4 * 1024 * 1024; // 4MB in bytes

// 获取输入的视频二进制数据
const binaryData = items[0].binary.data;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// 计算需要分成多少块
const totalChunks = Math.ceil(buffer.length / CHUNK_SIZE);
const chunks = [];

// 分割二进制数据
for (let i = 0; i < totalChunks; i++) {
  const start = i * CHUNK_SIZE;
  const end = Math.min(start + CHUNK_SIZE, buffer.length);
  const chunkBuffer = buffer.slice(start, end);

  // 为每个块创建新的二进制数据对象
  chunks.push({
    json: {
      chunkIndex: i,
      totalChunks: totalChunks,
      chunkSize: chunkBuffer.length,
      originalFileName: binaryData.fileName || 'video'
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        chunkBuffer,
        `${binaryData.fileName || 'video'}_chunk_${i}.bin`
      )
    }
  });
}

return chunks;

// 节点功能：把某个上游节点的 json 和 binary 重新挂到当前输出上
// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)

return {
  json: $('获取视频文件大小').item.json,
  binary: $('获取视频文件大小').item.binary,
};

