// 节点功能：对获取到的素材(图片、视频、音频)文件进行拼接
// Author:@新哥AGI研习社

const files = $input.first().json.data;

// 按类型分组
const imageLike = files.filter(i => i.type === 'image/jpeg' || i.type === 'video/mp4');
const audioLike = files.filter(i => i.type === 'audio/mpeg');

// 1) 按照 MoneyPrinterTurbo 规范组装本地视频/图片素材列表
const imagesArray = imageLike.map(i => {
  const fileTokenName = `${i.file_token}_${i.name}`;

  // 1. 根据后缀名或 type 严格区分 image 和 video
  const isVideo = i.name.endsWith('.mp4') || i.type === 'video/mp4';

  return {
    provider: 'local',
    type: isVideo ? 'video' : 'image', // 务必对应正确！
    url: `/MoneyPrinterTurbo/storage/local_videos/${fileTokenName}`,
    duration: 0
  };
});

// ⚠️ 注意：直接保留对象数组（Array），不要在此处使用 JSON.stringify！
const images = imagesArray; 

// 2) 当类型为 audio/mpeg 按照 MoneyPrinterTurbo 的格式要求封装为字符串输出
let audio = '';
if (audioLike.length > 0) {
  const i = audioLike[0]; // 只取第一条
  const fileTokenName = `${i.file_token}_${i.name}`;
  audio = `/MoneyPrinterTurbo/storage/local_videos/${fileTokenName}`;
}

// 只输出一条 item，把两种结果都放进同一个对象里
return [
  {
    json: {
      images, 
      audio, 
    },
  },
];

