  const fileTokenName = `${i.file_token}_${i.name}`;
  return {
    provider: 'local',
    url: `/MoneyPrinterTurbo/storage/local_files/${fileTokenName}`,
    duration: 0,
  };
});
const images = JSON.stringify(imagesArray); 

// 2) 当类型为audio/mpeg 按照MoneyPrinterTrubo的格式要求封装为字符串输出
let audio = '';
if (audioLike.length > 0) {
  const i = audioLike[0]; // 只取第一条
  const fileTokenName = `${i.file_token}_${i.name}`;
  audio = `/MoneyPrinterTurbo/storage/local_files/${fileTokenName}`;
}

// 只输出一条 item，把两种结果都放进同一个对象里
return [
  {
    json: {
      images, 
      audio, 
    },
  },
];

